import{_ as l,H as a,f as i,i as t}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"16 | 算力（二）：私有化部署大模型到底有多贵？","description":"","frontmatter":{},"headers":[{"level":2,"title":"情况二：使用云端私有化部署模型的成本计算","slug":"情况二-使用云端私有化部署模型的成本计算","link":"#情况二-使用云端私有化部署模型的成本计算","children":[{"level":3,"title":"预备知识：GPU 芯片的三大核心参数","slug":"预备知识-gpu-芯片的三大核心参数","link":"#预备知识-gpu-芯片的三大核心参数","children":[]},{"level":3,"title":"推理成本（直接使用开源模型）","slug":"推理成本-直接使用开源模型","link":"#推理成本-直接使用开源模型","children":[]}]},{"level":2,"title":"所需显存≈模型参数所需存储空间× 1.2 = 模型参数量× 每个参数占用空间","slug":"所需显存≈模型参数所需存储空间×-1-2-模型参数量×-每个参数占用空间","link":"#所需显存≈模型参数所需存储空间×-1-2-模型参数量×-每个参数占用空间","children":[]},{"level":2,"title":"模型推理能力成本= 所需GPU卡型号XX的租赁价格× 租赁时长","slug":"模型推理能力成本-所需gpu卡型号xx的租赁价格×-租赁时长","link":"#模型推理能力成本-所需gpu卡型号xx的租赁价格×-租赁时长","children":[]},{"level":2,"title":"显存= 模型参数量× 每个参数占用空间× 1.2 = 9 × 10 ×","slug":"显存-模型参数量×-每个参数占用空间×-1-2-9-×-10-×","link":"#显存-模型参数量×-每个参数占用空间×-1-2-9-×-10-×","children":[]},{"level":2,"title":"2 × 1.2 = 21.6GB","slug":"_2-×-1-2-21-6gb","link":"#_2-×-1-2-21-6gb","children":[]},{"level":2,"title":"2.01 × 24（小时）× 30（天）× 2 = 2880元/月","slug":"_2-01-×-24-小时-×-30-天-×-2-2880元-月","link":"#_2-01-×-24-小时-×-30-天-×-2-2880元-月","children":[{"level":3,"title":"微调成本","slug":"微调成本","link":"#微调成本","children":[]}]},{"level":2,"title":"FP16精度模型所需显存= 模型训练参数量× 20","slug":"fp16精度模型所需显存-模型训练参数量×-20","link":"#fp16精度模型所需显存-模型训练参数量×-20","children":[]},{"level":2,"title":"训练时长= 模型训练参数量× 训练数据量× 6/芯片型号XX的FLOPS数/G","slug":"训练时长-模型训练参数量×-训练数据量×-6-芯片型号xx的flops数-g","link":"#训练时长-模型训练参数量×-训练数据量×-6-芯片型号xx的flops数-g","children":[]},{"level":2,"title":"微调成本= 训练时长× 芯片的租赁单价","slug":"微调成本-训练时长×-芯片的租赁单价","link":"#微调成本-训练时长×-芯片的租赁单价","children":[]},{"level":2,"title":"所需显存= 20 ×","slug":"所需显存-20-×","link":"#所需显存-20-×","children":[]},{"level":2,"title":"9 = 180GB","slug":"_9-180gb","link":"#_9-180gb","children":[]},{"level":2,"title":"训练时长= 模型训练参数量× 训练数据量× 6/A100的FLOPS数/GPU计算","slug":"训练时长-模型训练参数量×-训练数据量×-6-a100的flops数-gpu计算","link":"#训练时长-模型训练参数量×-训练数据量×-6-a100的flops数-gpu计算","children":[]},{"level":2,"title":"情况三：自采硬件私有化部署的成本计算","slug":"情况三-自采硬件私有化部署的成本计算","link":"#情况三-自采硬件私有化部署的成本计算","children":[]},{"level":2,"title":"9 × 2 × 1.2 = 21.6GB","slug":"_9-×-2-×-1-2-21-6gb","link":"#_9-×-2-×-1-2-21-6gb","children":[]},{"level":2,"title":"所需显存= 20 × 9 = 180GB","slug":"所需显存-20-×-9-180gb","link":"#所需显存-20-×-9-180gb","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"课后题","slug":"课后题","link":"#课后题","children":[]},{"level":2,"title":"参考总结","slug":"参考总结","link":"#参考总结","children":[]}],"relativePath":"成为AGI产品经理/16｜算力（二）：私有化部署大模型到底有多贵？.md","filePath":"成为AGI产品经理/16｜算力（二）：私有化部署大模型到底有多贵？.md","lastUpdated":1795557342000}'),r={name:"成为AGI产品经理/16｜算力（二）：私有化部署大模型到底有多贵？.md"};function n(p,e,o,h,s,u){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="_16-算力-二-私有化部署大模型到底有多贵" tabindex="-1">16 | 算力（二）：私有化部署大模型到底有多贵？ <a class="header-anchor" href="#_16-算力-二-私有化部署大模型到底有多贵" aria-label="Permalink to &quot;16 | 算力（二）：私有化部署大模型到底有多贵？&quot;">​</a></h1><p>你好，我是产品二姐。</p><p>上节课，我们介绍了 AI 产品中直接调用模型厂商接口的成本计算方法，这也是 AI 应用最容易起步的方法。但随着 AI 逐步深入各种场景，尤其是企业场景里，这种直接调用的方法并不友好。</p><p>比如企业希望大模型能对内部的业务数据进行分析、总结，但考虑到数据安全，企业无法接受将业务数据直接发给模型厂商，比如我们在第 12 节就遇到了类似的诉求。</p><p>而私有化部署开源模型能保障所有和模型交互的数据不外泄，企业可以更自由地把大语言模型与企业数据库、业务接口集成在自己的 AI 产品中。比如用户可以直接问“这个月的工厂产量有多少”，AI 应用就可以直接读取企业数据库，拿到这个数据。同时，一些企业在 AI 建设初期也希望避免大额硬件投资。</p><p>于是，将开源模型私有化部署在云端成为另一种选择。</p><p>这节课，我就来介绍一下这种部署方式的算力成本计算方法。</p><p>同样需要提醒大家：本文所有价格示例均为作者撰写课程内容时的价格，通用模型 API Token价格、私有云厂商的资源租赁价格和硬件价格变化幅度都会比较大，请大家参考时价计算。</p><h2 id="情况二-使用云端私有化部署模型的成本计算" tabindex="-1">情况二：使用云端私有化部署模型的成本计算 <a class="header-anchor" href="#情况二-使用云端私有化部署模型的成本计算" aria-label="Permalink to &quot;情况二：使用云端私有化部署模型的成本计算&quot;">​</a></h2><p>我们继续用发电站做类比：不同的发电机体量，对厂房的要求也不一样；发电机越大，对厂房要求也更高；并且如果大到需要多个厂房的时候，厂房之间的数据通讯会降低单个厂房的使用率。</p><p>OK，翻译一下。不同的开源模型对 GPU 云资源的要求也不一样。比如参数量较小的 1B 开源模型在单张英伟达 4090 GPU 卡上就能实现微调。而 7B 以上的开源模型，在单张 4090 上就会显得有些局促，那么就需要多张 GPU 资源来支撑。对需要用到多个 GPU 云资源的情况，GPU 之间的数据通讯会降低单个厂房的使用率。目前来说，这个使用率在 0.3~0.55 之间[参考 1]。</p><p>明白这一点后，我们再分推理、微调两种情况来拆解成本计算的核心任务。</p><ul><li><p>推理成本。这是持续支出，需要根据模型参数量计算所需显存资源，也就是租什么配置的GPU 卡。</p></li><li><p>模型微调：这是一次性支出，需要根据模型参数量计算所需显存资源、根据训练数据量计算所需时长。</p></li></ul><h3 id="预备知识-gpu-芯片的三大核心参数" tabindex="-1">预备知识：GPU 芯片的三大核心参数 <a class="header-anchor" href="#预备知识-gpu-芯片的三大核心参数" aria-label="Permalink to &quot;预备知识：GPU 芯片的三大核心参数&quot;">​</a></h3><p>在具体计算之前，我们先准备一下 GPU 芯片的相关知识。</p><p>下图是 Nvidia 官网上对于 A100 芯片的参数介绍[参考 2]。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/16/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/16/1.png" alt=""></a></p><p>不用觉得复杂，我们重点关注三个指标就好，分别是显存、计算速度、GPU 带宽。</p><ol><li>显存，是指 GPU 芯片能存储的数据量，也是选择 GPU 芯片配置的首要因素。</li></ol><p>我们知道，大语言模型的本质是十亿、百亿甚至是千亿个参数组成的数值矩阵。我们假设每个参数是 16 位精度的浮点数，占 2 个字节，把这些参数加载到 GPU 里，则需要巨大的存储空间。</p><p>比如 7B 模型，占用 140 亿个字节，即 14GB 的存储空间。对于推理场景来说，GPU 显存主要是用来存储模型参数矩阵的；而对于训练（微调）场景，那就还要存储计算过程中所产生的临时数据需要的显存。</p><ol start="2"><li>峰值计算次数，是指 GPU 的计算速度。</li></ol><p>GPU 计算速度， 单位是 FLOPS（FLoating point Operations Per Second）， 即每秒浮点计算次数。对于不同精度 64 位、32 位、16 位、8 位的要求，计算速度也不同。主流大模型大多采用 16 位精度。在满足显存的条件下，FLOPS 主要会影响训练或推理所需时长。</p><p>需要注意的是，图上标出的“标准计算次数”是峰值计算次数，实际使用时，因为受多种因素影响，实际计算速率是峰值的 0.3~0.55 倍。</p><ol start="3"><li>GPU 带宽：是指卡与卡之间的数据传递速度。</li></ol><p>在多卡共同参与训练、推理时，带宽显得尤为重要，它就像是卡和卡之间的高速公路，带宽过窄会引发“计算堵车”，影响训练、推理进度。如果由于显存需求同时使用多张卡时，就必须保证高带宽。</p><p>按照这三个指标，会有不同的 GPU 云端资源，也对应着不同的租金价格。我在这里列出了几款常见英伟达 GPU 芯片的关键指标和价格，你可以参考。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/16/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/16/2.png" alt=""></a></p><h3 id="推理成本-直接使用开源模型" tabindex="-1">推理成本（直接使用开源模型） <a class="header-anchor" href="#推理成本-直接使用开源模型" aria-label="Permalink to &quot;推理成本（直接使用开源模型）&quot;">​</a></h3><p>在云端私有化部署模型中，模型部署所需的显存空间主要是用来加载模型参数的。我们再加上20% 作为冗余空间，那么计算公式就是：</p><h2 id="所需显存≈模型参数所需存储空间×-1-2-模型参数量×-每个参数占用空间" tabindex="-1">所需显存≈模型参数所需存储空间× 1.2 = 模型参数量× 每个参数占用空间 <a class="header-anchor" href="#所需显存≈模型参数所需存储空间×-1-2-模型参数量×-每个参数占用空间" aria-label="Permalink to &quot;所需显存≈模型参数所需存储空间× 1.2 = 模型参数量× 每个参数占用空间&quot;">​</a></h2><p>得出了这个数字，再根据模型参数量计算选择所需的 GPU 卡型号。确定型号之后，再乘以相应的租赁单价即可，即：</p><h2 id="模型推理能力成本-所需gpu卡型号xx的租赁价格×-租赁时长" tabindex="-1">模型推理能力成本= 所需GPU卡型号XX的租赁价格× 租赁时长 <a class="header-anchor" href="#模型推理能力成本-所需gpu卡型号xx的租赁价格×-租赁时长" aria-label="Permalink to &quot;模型推理能力成本= 所需GPU卡型号XX的租赁价格× 租赁时长&quot;">​</a></h2><p>我来举个例子。比如私有化部署清华智谱的 GLM-4-9B 模型，模型参数量大小是 9B，参数精度是 FP16(（6 位浮点精度）。</p><p>我们首先计算“所需显存”。</p><ul><li>9</li></ul><h2 id="显存-模型参数量×-每个参数占用空间×-1-2-9-×-10-×" tabindex="-1">显存= 模型参数量× 每个参数占用空间× 1.2 = 9 × 10 × <a class="header-anchor" href="#显存-模型参数量×-每个参数占用空间×-1-2-9-×-10-×" aria-label="Permalink to &quot;显存= 模型参数量× 每个参数占用空间× 1.2 = 9 × 10 ×&quot;">​</a></h2><h2 id="_2-×-1-2-21-6gb" tabindex="-1">2 × 1.2 = 21.6GB <a class="header-anchor" href="#_2-×-1-2-21-6gb" aria-label="Permalink to &quot;2 × 1.2 = 21.6GB&quot;">​</a></h2><p>这个 21.6GB 代表着租用显存为 24G 的英伟达 4090 型号的 GPU 显卡刚刚够，保险起见，我们可以租用 2 张来使用。</p><p>如果参考某租赁平台的价格为 2.01/ 卡 / 小时，那么部署 GLM-4-9B 模型，仅仅使用模型做推</p><h2 id="_2-01-×-24-小时-×-30-天-×-2-2880元-月" tabindex="-1">2.01 × 24（小时）× 30（天）× 2 = 2880元/月 <a class="header-anchor" href="#_2-01-×-24-小时-×-30-天-×-2-2880元-月" aria-label="Permalink to &quot;2.01 × 24（小时）× 30（天）× 2 = 2880元/月&quot;">​</a></h2><p>理，成本最少就是</p><ul><li>。</li></ul><h3 id="微调成本" tabindex="-1">微调成本 <a class="header-anchor" href="#微调成本" aria-label="Permalink to &quot;微调成本&quot;">​</a></h3><p>和我们上节课说的情况一类似，单纯地使用开源模型做推理，往往不能适配具体业务场景。这时候就需要对模型进行微调。</p><p>和模型推理成本相比，模型微调成本不是持续支出，而是按照次数来算的，计算分 3 步走。</p><ol><li>计算所需 GPU 显存，得出对应 GPU 型号 xx。</li></ol><p>在02这节课我们讲过，模型训练就是通过反复使用前向传播和反向传播算法，逐步改变模型参数的值，直到模型的实际输出和期待输出达到一定程度，训练完成。所以，这个过程就不仅需要存储模型参数，还需要存储大量计算中间值。</p><p>以 FP16 精度为例，总共需要参数大小空间的 20 倍（这里的 20 倍的推理过程，你可以阅读参考[1]）。即：</p><h2 id="fp16精度模型所需显存-模型训练参数量×-20" tabindex="-1">FP16精度模型所需显存= 模型训练参数量× 20 <a class="header-anchor" href="#fp16精度模型所需显存-模型训练参数量×-20" aria-label="Permalink to &quot;FP16精度模型所需显存= 模型训练参数量× 20&quot;">​</a></h2><p>这里还有一个细节。所谓的“模型训练参数量”并不是模型全部参数量，而是会根据不同微调方法变化。我们在 02 这节课讲到，在全参微调中，它和模型全部参数量一致；在参数高效微调中，比如 Lora 微调中，这个参数量就是最终低秩化后的训练参数，可能是模型参数量的百分之一、千分之一。</p><ol start="2"><li>计算微调所需计算时长</li></ol><p>还是在 02 这节课，我们讲过模型训练过程中的计算发生在神经网络的前向传播和反向传播中。在每一次前向传递中，对于每个 token、每个模型参数，需要进行 2 次浮点数运算，也就是一次乘法运算和一次加法运算。</p><p>一次训练迭代包含了前向传播和反向传播，反向传播的计算量是前向传播的 2 倍，所以每个token、每个模型参数，一共需要 2✖️（1+2）=6 次计算（参考[1][3]）。</p><p>根据 GPU 型号 xx 的每秒计算次数和微调所需计算次数 N，再考虑 GPU 计算有效率 0.3～0.55，就能得出所需训练时长。即：</p><h2 id="训练时长-模型训练参数量×-训练数据量×-6-芯片型号xx的flops数-g" tabindex="-1">训练时长= 模型训练参数量× 训练数据量× 6/芯片型号XX的FLOPS数/G <a class="header-anchor" href="#训练时长-模型训练参数量×-训练数据量×-6-芯片型号xx的flops数-g" aria-label="Permalink to &quot;训练时长= 模型训练参数量× 训练数据量× 6/芯片型号XX的FLOPS数/G&quot;">​</a></h2><ol start="3"><li>计算云资源租赁价格</li></ol><p>根据第二步计算得到的时长，乘以 GPU 芯片的租赁单价，得到云资源消耗成本。即：</p><h2 id="微调成本-训练时长×-芯片的租赁单价" tabindex="-1">微调成本= 训练时长× 芯片的租赁单价 <a class="header-anchor" href="#微调成本-训练时长×-芯片的租赁单价" aria-label="Permalink to &quot;微调成本= 训练时长× 芯片的租赁单价&quot;">​</a></h2><p>好，我们还是以 GLM-4-9B 为例，尝试计算一遍整个过程。</p><h2 id="所需显存-20-×" tabindex="-1">所需显存= 20 × <a class="header-anchor" href="#所需显存-20-×" aria-label="Permalink to &quot;所需显存= 20 ×&quot;">​</a></h2><p>假设要进行全参微调 (训练参数量为 9B)，微调数据量为 1GB。那么</p><h2 id="_9-180gb" tabindex="-1">9 = 180GB <a class="header-anchor" href="#_9-180gb" aria-label="Permalink to &quot;9 = 180GB&quot;">​</a></h2><ul><li>。</li></ul><p>如果我们采用 Nvidia A100（显存 80G，带宽为 2TB/s），且至少需要 3 张 A100。</p><p>假定 GPU 计算效率为 0.4， 训练精度为 FP16，那么：</p><h2 id="训练时长-模型训练参数量×-训练数据量×-6-a100的flops数-gpu计算" tabindex="-1">训练时长= 模型训练参数量× 训练数据量× 6/A100的FLOPS数/GPU计算 <a class="header-anchor" href="#训练时长-模型训练参数量×-训练数据量×-6-a100的flops数-gpu计算" aria-label="Permalink to &quot;训练时长= 模型训练参数量× 训练数据量× 6/A100的FLOPS数/GPU计算&quot;">​</a></h2><p>参考某平台 A100 的租赁价格约 28 元 / 小时，最后算出一次全参微调所需的租赁价格为：3360 元。</p><p>当然，更多的时候，我们会采用像 12 节中提到的参数高效微调的方法来训练，这时训练参数量可能会降低为全参微调的百分之一、千分之一。</p><h2 id="情况三-自采硬件私有化部署的成本计算" tabindex="-1">情况三：自采硬件私有化部署的成本计算 <a class="header-anchor" href="#情况三-自采硬件私有化部署的成本计算" aria-label="Permalink to &quot;情况三：自采硬件私有化部署的成本计算&quot;">​</a></h2><p>最后我们来看一下如果企业要自购裸金属硬件所需成本。</p><p>这种方式一般适合对安全程度要求非常高的场景，比如公司的核心财务信息、国家政府的保密单位等等。这种方式的计算步骤和上一小节步骤类似。</p><p>对于推理场景来说，根据模型大小算出显存诉求，选中对应型号直接购买即可。</p><h2 id="_9-×-2-×-1-2-21-6gb" tabindex="-1">9 × 2 × 1.2 = 21.6GB <a class="header-anchor" href="#_9-×-2-×-1-2-21-6gb" aria-label="Permalink to &quot;9 × 2 × 1.2 = 21.6GB&quot;">​</a></h2><p>比如将 GLM-4-9B 私有化部署到本地，至少需要</p><ul><li>的 GPU 芯片，而</li></ul><p>24GB 的 4090 略显局促，可能需要购入 A100-40G。 价格约为 10 万元人民币。</p><h2 id="所需显存-20-×-9-180gb" tabindex="-1">所需显存= 20 × 9 = 180GB <a class="header-anchor" href="#所需显存-20-×-9-180gb" aria-label="Permalink to &quot;所需显存= 20 × 9 = 180GB&quot;">​</a></h2><ul><li>，需要 3 张 A100-80G 芯片，价格约</li></ul><p>对于训练场景来说，为人民币 60 万元。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>好了，到这里，我们就把 AI 应用落地过程中所需算力成本的计算方法讲完了。</p><p>要特别说明的是，咱们这节课里所有的价格都是参考网络公开价格，实际中的价格会有市场浮动，客户分群浮动，不能作为实际价格。在这里列出是为了大家有更直观的感受。大家在实际预估的时候更多的是参考我说的方法，而不是直接照抄数值。</p><p>最后，我们再一起来将上节课开头的那张表格填充完整，和上节课一样，给你总结了各自的“打油诗”，帮你记忆各个场景中的关键点。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/16/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%88%90%E4%B8%BAAGI%E4%BA%A7%E5%93%81%E7%BB%8F%E7%90%86/images/16/3.png" alt=""></a></p><h2 id="课后题" tabindex="-1">课后题 <a class="header-anchor" href="#课后题" aria-label="Permalink to &quot;课后题&quot;">​</a></h2><p>假设你的公司想要用大语言模型识别客户的反馈中是否带有抱怨情绪，考虑到数据安全因素，老板并不愿意把客户反馈发给通用大模型，但他又担心私有化部署会很贵，希望你做一个算力成本预算报告给 ta。这时该怎么做呢？</p><p>你可以使用 LlaMA-7B 的模型，训练数据使用 02 节课中下载的标注了是否含有抱怨情绪的Twitter 文本数据集。按照本文的方法，分别计算出：</p><ul><li><p>使用云端资源私有化部署的推理成本（GPU 租金）和微调成本。</p></li><li><p>自采硬件私有化部署的推理和微调成本（采购 GPU 硬件）</p></li></ul><h2 id="参考总结" tabindex="-1">参考总结 <a class="header-anchor" href="#参考总结" aria-label="Permalink to &quot;参考总结&quot;">​</a></h2><ol><li><p>分析 transformer 模型的参数量、计算量、中间激活、KV cache。</p></li><li><p>Nvidia A100 卡介绍。</p></li><li><p>浅谈后向传递的计算量大约是前向传递的两倍。</p></li></ol>',91)])])}const g=l(r,[["render",n]]);export{c as __pageData,g as default};
